"""Example 4: Use frozenset to cache results by argument set."""

def cache_by_args(fn):
    """Memoize a function based on its positional args (order-independent)."""
    cache: dict[frozenset, object] = {}

    def wrapper(*args):
        key = frozenset(args)  # order-independent
        if key not in cache:
            cache[key] = fn(*args)
        return cache[key]

    wrapper.cache = cache  # for inspection
    return wrapper

@cache_by_args
def expensive_combine(*nums: int) -> int:
    """Simulate expensive operation — sum + product."""
    print(f"  computing for {nums}")
    return sum(nums) * sum(n * n for n in nums)

print("=== Order-independent caching ===")
print(expensive_combine(1, 2, 3))   # computes
print(expensive_combine(3, 2, 1))   # cached! (same frozenset)
print(expensive_combine(1, 2, 3, 4))  # computes (different set)
print(f"cache keys: {list(expensive_combine.cache.keys())}")

print("\n=== frozenset as set element ===")
sets_of_sets = {
    frozenset({1, 2, 3}),
    frozenset({4, 5}),
    frozenset({1, 2, 3}),  # dup — will be deduplicated
}
print(f"  set of frozensets: {sets_of_sets}")  # 2 elements
