"""Example 6: Build sets efficiently with comprehensions."""

# Set comprehension — like list comprehension but dedupes
squares = {x * x for x in range(10)}
print(f"  squares: {squares}")

# Filtered set comprehension
even_squares = {x * x for x in range(10) if x % 2 == 0}
print(f"  even squares: {even_squares}")

# From a generator (memory-efficient for large sources)
def generate_ids():
    """Yield IDs from a 'database'."""
    for i in range(1_000_000):
        yield i

# Don't materialize — stream into set
unique_ids = set()
for x in generate_ids():
    if x % 7 == 0:
        unique_ids.add(x)
        if len(unique_ids) >= 100:
            break
print(f"  collected {len(unique_ids)} unique multiples of 7")

# Multiple set comprehension with conditional
print("\n=== Multi-source comprehension ===")
a = {1, 2, 3, 4, 5}
b = {4, 5, 6, 7, 8}
cartesian_subset = {x + y for x in a for y in b if x < y}
print(f"  {{x+y for x in a for y in b if x<y}} = {cartesian_subset}")
